import numpy as np
from PIL import Image
f=np.load('source_pixels.npz')['rgb']
print('shape',f.shape)
for i in range(96):
    d=np.abs(f[i].astype(np.int16)-f[max(0,i-1)].astype(np.int16)).max(2)
    ys,xs=np.where(d>20)
    if i<10 or i%5==0:
        if len(xs): print(i, 'changed',len(xs),'bbox',(xs.min(),ys.min(),xs.max(),ys.max()),'mean',f[i].mean())
        else: print(i,'none','mean',f[i].mean())
# whole sequence std map, first vs last
std=f.astype(np.float32).std(0).max(2)
for th in [5,10,20,40,80]: print('std>',th,(std>th).sum())
for i in [0,1,2,10,24,48,72,95]:
    Image.fromarray(f[i]).resize((1024,576),Image.Resampling.NEAREST).save(f'[workspace path]')
print('saved')
