import numpy as np
f=np.load('source_pixels.npz')['rgb'].astype(np.int16)
for th in [3,6,12,24,48]:
 print('\\nTH',th)
 for i in range(30):
  d=np.abs(f[i]-f[i-1]).max(2) if i else np.zeros(f.shape[1:],bool)
  ys,xs=np.where(d>th)
  if len(xs):
   print(f'{i:2d} n={len(xs):4d} bbox={xs.min():3d},{ys.min():2d}-{xs.max():3d},{ys.max():2d} cen={xs.mean():6.2f},{ys.mean():5.2f}')
  else: print(f'{i:2d} none')
